Object.assign(window.deepArticles,{
  "central-american-crisis":centralAmericanCrisisArticle({title:"Central American Crisis",category:"Regional conflicts",eyebrow:"1960s–1980s · insurgency, intervention, and mediation",infoboxKicker:"Regional conflict system",
    lead:"The Central American Crisis was the connected period of insurgency, military government, foreign intervention, refugee movement, and interstate tension that affected the isthmus from the 1960s through the 1980s. It included the American client system in <a href='honduras.html'>Honduras</a>, the <a href='nicaraguan-proxy-war.html'>Nicaraguan Proxy War</a>, prolonged conflicts in <a href='guatemalan-insurgency.html'>Guatemala</a> and <a href='salvadoran-insurgency.html'>El Salvador</a>, and the diplomatic role of <a href='costa-rica.html'>Costa Rica</a>.",
    canon:"The regional security pattern, principal national conflicts, American corridor, Cuban and Latin support for Nicaraguan opposition, Honduran staging role, Costa Rican mediation, and conditions in 1985 are established. Exact common periodization, combined casualty totals, formal names of several insurgent coalitions, and the end dates of the Guatemalan and Salvadoran conflicts remain open.",
    sections:[
      {id:"background",title:"Background",html:"<p>Unequal landholding, export dependence, military government, foreign concessions, rapid population growth, migration, and restricted legal opposition preceded the crisis. These causes survived the disappearance of a Soviet-centered revolutionary system.</p>"},
      {id:"american",title:"American policy",html:"<p>Washington treated the Caribbean coast, canal approaches, airfields, ports, and communications routes as one security problem. The successful <a href='honduran-security-crisis.html'>1962 intervention in Honduras</a> supplied bases and a reliable logistical state for later operations.</p>"},
      {id:"nicaragua",title:"Nicaragua",html:"<p>The weakening of the <a href='somoza-dynasty.html'>Somoza dynasty</a> produced the region's principal proxy war. A broad nationalist opposition, Guard remnants, American-backed forces, Cuban assistance, and competing Latin networks prevented either an uncontested revolutionary state or a restored family dictatorship.</p>"},
      {id:"northern",title:"Guatemala and El Salvador",html:"<p>Guatemalan conflict joined Indigenous exclusion, land disputes, military zones, religious division, and resistance to foreign companies. Salvadoran conflict joined rural land pressure, labor organization, Catholic social activism, urban radicalism, and state repression.</p>"},
      {id:"honduras",title:"Honduras",html:"<p>Honduras provided roads, airfields, depots, advisers, communications, and frontier access. American assistance increased state capacity while tying domestic appointments, budgets, and foreign policy to regional security requirements.</p>"},
      {id:"costa-rica",title:"Costa Rican diplomacy",html:"<p>Costa Rica maintained a civilian republic without a standing army. San José hosted negotiations, church diplomacy, prisoner exchanges, refugee conferences, and discreet contacts because governments that distrusted one another still required a meeting place.</p>"},
      {id:"foreign",title:"Foreign participation",html:"<p>Cuba provided the most direct aid to anti-American Nicaraguan factions. Spain, Italy, and other Latin states supplied diplomatic, religious, publication, exile, and commercial networks. American policy excluded permanent rival military missions while tolerating less strategic forms of influence.</p>"},
      {id:"legacy",title:"Regional position in 1985",html:"<p>By 1985 most of Central America lay inside the American security environment. Costa Rica remained Neutral / Independent, Nicaragua retained armed exclusion zones under an uneasy settlement, and the Guatemalan and Salvadoran conflicts continued without complete political settlements.</p>"}
    ],
    related:[{href:"central-american-security-corridor.html",kicker:"Security geography",label:"Central American Security Corridor"},{href:"nicaraguan-proxy-war.html",kicker:"Principal proxy war",label:"Nicaraguan Proxy War"},{href:"guatemalan-insurgency.html",kicker:"Northern conflict",label:"Guatemalan Insurgency"},{href:"salvadoran-insurgency.html",kicker:"Pacific conflict",label:"Salvadoran Insurgency"},{href:"honduran-security-crisis.html",kicker:"American precedent",label:"Honduran Security Crisis"},{href:"american-hemisphere.html",kicker:"Wider strategic system",label:"American Hemisphere"}],
    categories:["Central American Crisis","American Hemisphere","Proxy wars","Postwar conflicts"],
    facts:[["Period","1960s–1980s"],["Principal external power","United States"],["Principal proxy battlefield","Nicaragua"],["American logistics state","Honduras"],["Neutral diplomatic state","Costa Rica"],["Other principal conflicts","Guatemala and El Salvador"],["Soviet direction","Absent"],["Regional settlement","Incomplete in 1985"]]
  }),
  "central-american-security-corridor":centralAmericanCrisisArticle({title:"Central American Security Corridor",category:"American foreign policy",eyebrow:"1962 onward · Caribbean and canal approaches",infoboxKicker:"Regional security system",
    lead:"The Central American Security Corridor is the name given to the American-aligned chain of ports, airfields, roads, communications stations, military missions, and client governments between Mexico, the Caribbean, and the Panama Canal. Its most dependable land node is <a href='honduras.html'>Honduras</a>, while Guatemala, El Salvador, Nicaragua, and Panama occupy different positions within the same system.",
    canon:"The corridor's geography, origin in the Honduran intervention, American denial policy, Honduran logistical role, varied sovereignty of member states, relationship to Cuba and the canal, and 1985 extent are established. No single founding statute, formal membership list, or unified command is established.",
    sections:[
      {id:"origin",title:"Origins",html:"<p>The corridor developed after the <a href='honduran-security-crisis.html'>Honduran Security Crisis</a> demonstrated that a rapid American intervention could install a durable client administration. Later crises were managed through access agreements, missions, local forces, credit, and intelligence rather than one permanent occupation army.</p>"},
      {id:"geography",title:"Geography",html:"<p>The system joins the Gulf of Mexico, the western Caribbean, Central American Pacific ports, and the Panama Canal. Roads and air routes through Honduras connect Guatemala and El Salvador to Caribbean supply while Panama anchors the southern transit point.</p>"},
      {id:"installations",title:"Installations",html:"<p>Facilities include airfields, fuel storage, radio and radar stations, training grounds, customs posts, road depots, medical stations, and guarded port districts. Many remain legally national installations operated with American personnel or contracts.</p>"},
      {id:"missions",title:"Military missions",html:"<p>American missions provide communications, air transport, engineering, police training, light armor, intelligence, and credit. Their authority varies by country: nearly directive in Honduras, negotiated with local officers elsewhere, and deliberately limited in Costa Rica.</p>"},
      {id:"nicaragua",title:"Nicaraguan war",html:"<p>Honduran territory supported American-backed factions during the <a href='nicaraguan-proxy-war.html'>Nicaraguan Proxy War</a>. Washington preferred advisers, logistics, air surveillance, and local formations to another full occupation after the Philippine War.</p>"},
      {id:"sovereignty",title:"Sovereignty",html:"<p>States inside the corridor retain flags, ministries, armed forces, and domestic political machines. Control of bases, ports, communications, and foreign military access remains the practical test that Washington applies to their sovereignty.</p>"},
      {id:"rivals",title:"Rival influence",html:"<p>Cuba and Latin states operate through political, Catholic, publishing, banking, and commercial networks. American authorities tolerate ordinary business and culture but oppose rival control of strategic communications, coastlines, oil, or armed formations.</p>"},
      {id:"later",title:"Later development",html:"<p>By the 1990s American companies increasingly supplement government missions through telecommunications, finance, logistics, construction, and guarded concessions. Corporate reach does not erase the older state-security chain.</p>"}
    ],
    related:[{href:"central-american-crisis.html",kicker:"Conflict system",label:"Central American Crisis"},{href:"honduran-security-crisis.html",kicker:"Founding precedent",label:"Honduran Security Crisis"},{href:"nicaraguan-proxy-war.html",kicker:"Principal intervention theater",label:"Nicaraguan Proxy War"},{href:"panama.html",kicker:"Southern anchor",label:"Panama"},{href:"american-continental-defense-system.html",kicker:"Continental framework",label:"American Continental Defense System"},{href:"american-hemisphere.html",kicker:"Strategic sphere",label:"American Hemisphere"}],
    categories:["Central American Security Corridor","American foreign policy","Military logistics","American Hemisphere"],
    facts:[["Developed","After 1962"],["Principal land node","Honduras"],["Southern anchor","Panama Canal"],["Primary sponsor","United States"],["Legal form","Network of bilateral arrangements"],["Unified command","None established"],["Principal rival node","Cuba"],["Later extension","Corporate logistics and communications"]]
  }),
  "nicaraguan-proxy-war":centralAmericanCrisisArticle({title:"Nicaraguan Proxy War",category:"Wars involving Nicaragua",eyebrow:"Late 1970s–early 1980s · unfinished revolution",infoboxKicker:"Civil and proxy war",
    lead:"The Nicaraguan Proxy War was the civil conflict that followed the collapse of the <a href='somoza-dynasty.html'>Somoza dynasty</a>. A broad provisional opposition entered Managua, but armed nationalists, <a href='nicaraguan-national-guard.html'>National Guard</a> remnants, American-backed security forces, and Cuban- and Latin-supported factions disputed the composition and foreign alignment of the successor state.",
    canon:"The late-1970s revolutionary crisis, American pressure for Somoza exile, broad provisional coalition, factional break, Guard resistance to dissolution, Cuban and Latin support, Honduran support for the American-backed side, American refusal to accept a Cuban-aligned government, and an uneasy settlement around 1980–82 are established as the controlling framework. Exact dates, belligerent names, commanders, strengths, casualties, and front lines remain open.",
    sections:[
      {id:"background",title:"Background",html:"<p>The Somoza family controlled the presidency, property, patronage, and National Guard for decades. The <a href='managua-earthquake-1972.html'>1972 Managua earthquake</a>, disputed relief, corruption, economic exclusion, and repression widened opposition beyond the armed underground.</p>"},
      {id:"opposition",title:"Opposition coalition",html:"<p>Nationalist guerrillas, agrarian reformers, students, unions, Catholic social activists, democratic socialists, Conservatives, and excluded business families opposed the dynasty. Agreement on removing Somoza did not establish agreement on the next state.</p>"},
      {id:"collapse",title:"Collapse of the dynasty",html:"<p>During the late 1970s the regime lost administrative and commercial support. Washington pressed the family into exile rather than defend it without limit, and a broad provisional coalition entered Managua.</p>"},
      {id:"fracture",title:"Fracture of the provisional order",html:"<p>The armed nationalist wing rejected American security restrictions. Guard remnants rejected complete dissolution. Civilian coalition members lacked a single force capable of imposing the compromise across the country.</p>"},
      {id:"foreign",title:"Foreign support",html:"<p>The United States supported a government acceptable to its regional security system, using Honduras for logistics and access. Cuba supplied the most direct assistance to anti-American factions. Spain and Italy supported different political, church, exile, and diplomatic networks.</p>"},
      {id:"operations",title:"Military pattern",html:"<p>Fighting combined urban seizures, Guard strongpoints, rural guerrilla zones, frontier infiltration, air and road interdiction, and armed exclusion areas. The absence of Soviet heavy sponsorship kept the conflict fragmented and materially dependent on regional patrons.</p>"},
      {id:"settlement",title:"Managua Settlement",html:"<p>The <a href='managua-settlement.html'>Managua Settlement</a> created a coalition civilian government, reorganized constabulary, partial integration of nationalist fighters, local elections, American access rights, and continuing armed exclusion zones.</p>"},
      {id:"aftermath",title:"Aftermath",html:"<p>The settlement placed Nicaragua inside the American security system without producing a stable democracy or completing disarmament. Later politics remained divided by the unfinished revolution and by disputes over foreign companies, currency, and security guarantees.</p>"}
    ],
    related:[{href:"nicaragua.html",kicker:"Country history",label:"Nicaragua"},{href:"sandinismo-nicaragua.html",kicker:"Opposition tradition",label:"Sandinismo in Nicaragua"},{href:"somoza-dynasty.html",kicker:"Deposed order",label:"Somoza Dynasty"},{href:"nicaraguan-national-guard.html",kicker:"Regime armed force",label:"Nicaraguan National Guard"},{href:"managua-settlement.html",kicker:"Political settlement",label:"Managua Settlement"},{href:"central-american-security-corridor.html",kicker:"American support system",label:"Central American Security Corridor"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Nicaraguan_Revolution",label:"Wikipedia — Nicaraguan Revolution (shared historical baseline)"}],categories:["Nicaraguan Proxy War","Wars involving Nicaragua","Proxy wars","American Hemisphere"],
    facts:[["Period","Late 1970s–early 1980s"],["Location","Nicaragua"],["Preceding regime","Somoza dynasty"],["American support route","Honduras"],["Principal anti-American patron","Cuba"],["Soviet patron","Absent"],["Political result","Coalition settlement"],["Exact casualties","Not established"]]
  }),
  "somoza-dynasty":centralAmericanCrisisArticle({title:"Somoza Dynasty",category:"Political families of Nicaragua",eyebrow:"1936–late 1970s · family security regime",infoboxKicker:"Political dynasty",
    lead:"The Somoza dynasty was the Nicaraguan political family that controlled the presidency, <a href='nicaraguan-national-guard.html'>National Guard</a>, state patronage, and a large private business estate from 1936 until the late-1970s revolutionary crisis. Its rulers were Anastasio Somoza García and his sons Luis Somoza Debayle and Anastasio Somoza Debayle.",
    canon:"The dynasty's historical origin, principal family rulers, National Guard control, American relationship, property and patronage system, succession after the elder Somoza's assassination, 1972 earthquake crisis, and fall during the late-1970s conflict are established. The exact date and route of the final exile in setting continuity remain open.",
    sections:[
      {id:"origin",title:"Origins",html:"<p>Anastasio Somoza García used command of the American-created National Guard to dominate national politics from 1936. Presidents outside the family did not end its control of coercion, appointments, and electoral machinery.</p>"},
      {id:"first",title:"Anastasio Somoza García",html:"<p>The founder combined the presidency, Guard command, American support, and acquisition of land and businesses. His assassination in 1956 transferred authority to his sons rather than ending the family system.</p>"},
      {id:"succession",title:"Family succession",html:"<p>Luis Somoza Debayle occupied the presidency while Anastasio Somoza Debayle developed military authority. The arrangement preserved family primacy through formal civilian offices and Guard command.</p>"},
      {id:"state",title:"Government and National Guard",html:"<p>The family used the Guard as army, gendarmerie, police, intelligence service, and political enforcement body. Loyal civilian officials, local notables, businesses, and party organizations extended control beyond the barracks.</p>"},
      {id:"property",title:"Property and patronage",html:"<p>Family enterprises, land, banking, construction, import licenses, relief contracts, and access to state credit linked public authority to private accumulation. Economic modernization created new firms and infrastructure while reinforcing unequal access.</p>"},
      {id:"america",title:"Relations with the United States",html:"<p>Washington valued the dynasty as an anti-rival government near the canal approaches. Support became more costly as corruption and repression turned American protection into a central opposition grievance.</p>"},
      {id:"earthquake",title:"The 1972 earthquake",html:"<p>The destruction of Managua placed emergency relief and reconstruction under the regime. Diversion, favoritism, and reconstruction disputes widened opposition among business, church, students, professionals, and urban residents.</p>"},
      {id:"fall",title:"Fall",html:"<p>By the late 1970s the family could no longer contain the combined political and armed opposition. American officials pressed for exile, but removal of the dynasty left the National Guard, nationalist fighters, and civilian coalition without an accepted division of power.</p>"}
    ],
    related:[{href:"nicaraguan-national-guard.html",kicker:"Principal institution",label:"Nicaraguan National Guard"},{href:"nicaraguan-proxy-war.html",kicker:"War ending the dynasty",label:"Nicaraguan Proxy War"},{href:"managua-earthquake-1972.html",kicker:"Legitimacy crisis",label:"1972 Managua Earthquake"},{href:"sandinismo-nicaragua.html",kicker:"Opposition tradition",label:"Sandinismo in Nicaragua"},{href:"nicaragua.html",kicker:"National history",label:"Nicaragua"},{href:"central-american-crisis.html",kicker:"Regional setting",label:"Central American Crisis"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Somoza_family",label:"Wikipedia — Somoza family (shared biographical baseline)"}],categories:["Somoza family","Political families of Nicaragua","Nicaraguan dictatorships","Nicaraguan history"],
    facts:[["Founded","1936"],["Founder","Anastasio Somoza García"],["Later rulers","Luis and Anastasio Somoza Debayle"],["Principal armed institution","National Guard"],["Principal foreign patron","United States"],["Capital","Managua"],["Major legitimacy crisis","1972 earthquake relief"],["Deposed","Late 1970s"]]
  }),
  "nicaraguan-national-guard":centralAmericanCrisisArticle({title:"Nicaraguan National Guard",category:"Military history of Nicaragua",eyebrow:"1925–early 1980s · Guardia Nacional",infoboxKicker:"Armed force and gendarmerie",
    lead:"The Nicaraguan National Guard (<em>Guardia Nacional de Nicaragua</em>) was the combined military, gendarmerie, police, and internal-security institution created under American occupation in 1925. It became the principal coercive instrument of the <a href='somoza-dynasty.html'>Somoza dynasty</a> and fragmented during the <a href='nicaraguan-proxy-war.html'>Nicaraguan Proxy War</a>.",
    canon:"Creation in 1925, American institutional origin, combined-service role, Tiscapa headquarters, Somoza control, corruption and repression, late-1970s combat, refusal of remnants to accept immediate dissolution, and partial reorganization under the Managua settlement are established. Exact wartime strength, unit list, post-settlement institutional title, and demobilization totals remain open.",
    sections:[
      {id:"creation",title:"Creation",html:"<p>The United States organized the Guard during its occupation to replace partisan armies with a nominally national constabulary. Training and command arrangements made it the strongest continuous armed institution in the republic.</p>"},
      {id:"organization",title:"Organization",html:"<p>The Guard contained ground forces, aviation, maritime detachments, police, intelligence, prisons, and local posts. Headquarters stood on Tiscapa Hill in Managua. Its combined jurisdiction reduced the distinction between military defense and political policing.</p>"},
      {id:"somoza",title:"Somoza control",html:"<p>Anastasio Somoza García rose through command of the Guard. Family members and loyal officers used appointments, promotion, procurement, and provincial commands to preserve the dynasty through changes of formal president.</p>"},
      {id:"missions",title:"Domestic missions",html:"<p>Guard units protected government offices, estates, transport, customs, and communications; suppressed strikes and armed opposition; collected intelligence; and reinforced local authorities. They also performed disaster and emergency duties.</p>"},
      {id:"foreign",title:"Foreign assistance",html:"<p>American weapons, training, communications, transport, and political support remained most important. The regime also purchased equipment through other commercial and diplomatic channels when American restrictions tightened.</p>"},
      {id:"repression",title:"Repression and corruption",html:"<p>Detention, torture, censorship, extrajudicial violence, confiscation, and participation in family patronage damaged the Guard's claim to be a national institution. Opposition organizations often treated the dynasty and the Guard as one target.</p>"},
      {id:"war",title:"Nicaraguan Proxy War",html:"<p>The Guard defended cities, roads, airfields, and regime strongpoints during the late-1970s crisis. Units fragmented after Somoza's exile; some surrendered, some entered negotiations, and others continued as armed remnants.</p>"},
      {id:"reorganization",title:"Reorganization",html:"<p>The <a href='managua-settlement.html'>Managua Settlement</a> provided for a reorganized national constabulary and partial integration of nationalist fighters. Guard identity, records, pensions, prosecutions, and local command remained sources of conflict.</p>"}
    ],
    related:[{href:"somoza-dynasty.html",kicker:"Controlling family",label:"Somoza Dynasty"},{href:"nicaraguan-proxy-war.html",kicker:"Final major conflict",label:"Nicaraguan Proxy War"},{href:"managua-settlement.html",kicker:"Reorganization settlement",label:"Managua Settlement"},{href:"sandinismo-nicaragua.html",kicker:"Principal opposition",label:"Sandinismo in Nicaragua"},{href:"nicaragua.html",kicker:"National setting",label:"Nicaragua"},{href:"central-american-security-corridor.html",kicker:"Regional patronage system",label:"Central American Security Corridor"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/National_Guard_(Nicaragua)",label:"Wikipedia — Nicaraguan National Guard (shared institutional baseline)"}],categories:["Nicaraguan National Guard","Military of Nicaragua","Gendarmerie","Somoza family"],
    facts:[["Founded","1925"],["Spanish name","Guardia Nacional de Nicaragua"],["Headquarters","Tiscapa Hill, Managua"],["Functions","Army, police, gendarmerie, and intelligence"],["Political patron","Somoza dynasty"],["Foreign origin","American occupation"],["Late-1970s status","Fragmented"],["Successor arrangement","Reorganized constabulary"]]
  }),
  "sandinismo-nicaragua":centralAmericanCrisisArticle({title:"Sandinismo in Nicaragua",category:"Political movements in Nicaragua",eyebrow:"1960s–1980s · nationalist revolutionary tradition",infoboxKicker:"Political movement",
    lead:"Sandinismo is the Nicaraguan nationalist and revolutionary tradition named for Augusto César Sandino. In the fractured postwar order it develops as a broad anti-dynastic movement rather than a unified Marxist–Leninist party, bringing together guerrillas, agrarian reformers, Catholic social activists, students, unions, democratic socialists, Conservatives, and excluded business families.",
    canon:"Use of Sandino's memory, broad non-Marxist character, principal social and political wings, opposition to Somoza, Cuban assistance to armed anti-American factions, Latin religious and exile networks, internal division after the dynasty's fall, partial integration under the Managua settlement, and continuing political identity are established. Formal organization names, leadership, faction labels, program documents, and election performance remain open.",
    sections:[
      {id:"sandino",title:"Sandino's memory",html:"<p>Sandino's resistance to American occupation supplied a national language of sovereignty, armed dignity, and opposition to foreign tutelage. The symbol remained available to Catholic, conservative, social-democratic, and revolutionary critics of Somoza.</p>"},
      {id:"formation",title:"Formation",html:"<p>Underground groups emerged among students, rural organizers, labor activists, exiles, and veterans of earlier opposition. They used the Sandinista name without reproducing one externally disciplined ideological party.</p>"},
      {id:"wings",title:"Political wings",html:"<p>Nationalist guerrillas emphasized sovereignty and armed struggle. Agrarian organizers emphasized land and credit. Catholic activists connected reform to social doctrine. Democratic opposition and excluded business families sought removal of the dynasty and restoration of legal competition.</p>"},
      {id:"armed",title:"Armed organizations",html:"<p>Rural columns, urban cells, student networks, and exile supply lines operated with different priorities. Command remained divided, and armed leaders did not automatically control the civilian opposition coalition.</p>"},
      {id:"foreign",title:"Foreign relations",html:"<p>Cuba supplied clandestine and military aid to the most anti-American factions. Spain, Italy, and other Latin states offered publication, church, exile, diplomatic, and financial networks. Germany avoided openly adopting the movement.</p>"},
      {id:"revolution",title:"Revolutionary crisis",html:"<p>Sandinista groups participated in the late-1970s collapse of the Somoza state. Their success removed the common enemy and exposed disagreements over American access, the Guard, property, elections, and the composition of the new security forces.</p>"},
      {id:"settlement",title:"Settlement politics",html:"<p>The Managua Settlement integrated some nationalist fighters into the reorganized state while leaving other zones and formations outside full government control. Sandinista parties and veterans' organizations remained active after the fighting declined.</p>"},
      {id:"legacy",title:"Political legacy",html:"<p>By 1985 Sandinismo denoted an unfinished national revolution rather than one governing doctrine. Governments disputed which factions were legitimate participants, foreign clients, criminals, or protected local forces.</p>"}
    ],
    related:[{href:"nicaraguan-proxy-war.html",kicker:"Principal conflict",label:"Nicaraguan Proxy War"},{href:"somoza-dynasty.html",kicker:"Principal opponent",label:"Somoza Dynasty"},{href:"nicaraguan-national-guard.html",kicker:"State armed force",label:"Nicaraguan National Guard"},{href:"managua-settlement.html",kicker:"Partial integration",label:"Managua Settlement"},{href:"nicaragua.html",kicker:"National politics",label:"Nicaragua"},{href:"cuba.html",kicker:"External supporter",label:"Cuba"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Sandinista_National_Liberation_Front",label:"Wikipedia — Sandinista National Liberation Front (shared historical comparison)"}],categories:["Sandinismo","Political movements in Nicaragua","Nicaraguan nationalism","Revolutionary movements"],
    facts:[["Namesake","Augusto César Sandino"],["Country","Nicaragua"],["Political form","Broad nationalist movement"],["Principal opponent","Somoza dynasty"],["Marxist monopoly","Absent"],["Armed patron","Cuba and regional networks"],["Postwar status","Partly integrated; partly armed"],["Formal organization","Not fully established"]]
  }),
  "managua-earthquake-1972":centralAmericanCrisisArticle({title:"1972 Managua Earthquake",category:"Earthquakes in Nicaragua",eyebrow:"23 December 1972 · destruction of the capital",infoboxKicker:"Natural disaster",
    lead:"The 1972 Managua earthquake struck the Nicaraguan capital shortly after midnight on 23 December. The magnitude 6.3 shock destroyed much of the central city, killed thousands, injured tens of thousands, and displaced roughly 300,000 people. Relief administration and reconstruction became a major crisis for the <a href='somoza-dynasty.html'>Somoza regime</a>.",
    canon:"The date, time, magnitude, shallow depth, destructive intensity, broad casualty ranges, displacement, physical destruction, Somoza emergency authority, relief controversy, dispersed reconstruction, and political effect are shared history retained in setting continuity. Exact alternate foreign-aid totals, contract awards, and later reconstruction projects remain open.",
    sections:[
      {id:"earthquake",title:"Earthquake",html:"<p>The shock occurred at 00:29 local time on 23 December 1972. Its shallow focus and proximity to Managua produced violent ground motion across a city with vulnerable masonry and concrete construction.</p>"},
      {id:"damage",title:"Damage",html:"<p>Central commercial and residential districts suffered collapse, fire, broken utilities, blocked roads, and loss of communications. Hospitals, government offices, shops, warehouses, and housing were damaged simultaneously.</p>"},
      {id:"casualties",title:"Casualties and displacement",html:"<p>Historical estimates place deaths between about 4,000 and 11,000, injuries near 20,000, and displacement near 300,000. The ranges remained disputed because records, neighborhoods, and emergency administration were disrupted.</p>"},
      {id:"response",title:"Emergency response",html:"<p>The National Emergency Committee and <a href='nicaraguan-national-guard.html'>National Guard</a> controlled access, relief distribution, transport, curfew, and security. Local residents, churches, medical personnel, foreign teams, and private companies conducted rescue and aid work.</p>"},
      {id:"aid",title:"Foreign aid",html:"<p>Food, medicine, shelter, equipment, and money arrived through American, Latin, and other international channels. Allocation depended upon damaged transport, Guard control, family networks, official permits, and emergency contracting.</p>"},
      {id:"controversy",title:"Relief controversy",html:"<p>Opposition newspapers, businesses, clergy, and foreign observers accused the regime and connected firms of diverting aid, favoring loyal clients, and profiting from reconstruction. The government denied that corruption explained the larger administrative failure.</p>"},
      {id:"reconstruction",title:"Reconstruction",html:"<p>Population and commerce dispersed beyond the ruined center. New roads, neighborhoods, markets, offices, and improvised commercial districts developed unevenly while large parts of the old center remained damaged or vacant.</p>"},
      {id:"politics",title:"Political consequences",html:"<p>The disaster weakened the dynasty among groups that had tolerated it for order and growth. Relief grievances joined repression, property disputes, exclusion from contracts, and armed opposition in the development of the late-1970s crisis.</p>"}
    ],
    related:[{href:"somoza-dynasty.html",kicker:"Government in power",label:"Somoza Dynasty"},{href:"nicaraguan-national-guard.html",kicker:"Emergency authority",label:"Nicaraguan National Guard"},{href:"nicaraguan-proxy-war.html",kicker:"Later political crisis",label:"Nicaraguan Proxy War"},{href:"managua-settlement.html",kicker:"Later national settlement",label:"Managua Settlement"},{href:"nicaragua.html",kicker:"Country history",label:"Nicaragua"},{href:"central-american-crisis.html",kicker:"Regional context",label:"Central American Crisis"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/1972_Nicaragua_earthquake",label:"Wikipedia — 1972 Nicaragua earthquake"}],categories:["1972 Nicaragua earthquake","Earthquakes in Nicaragua","Managua","Somoza family"],
    facts:[["Date","23 December 1972"],["Local time","00:29"],["Magnitude","6.3 Mw"],["Depth","About 10 km"],["Maximum intensity","IX"],["Estimated dead","4,000–11,000"],["Estimated injured","About 20,000"],["Estimated displaced","About 300,000"]]
  }),
  "managua-settlement":centralAmericanCrisisArticle({title:"Managua Settlement",category:"Peace agreements of Nicaragua",eyebrow:"c. 1980–1982 · coalition and security settlement",infoboxKicker:"Political settlement",
    lead:"The Managua Settlement is the collective name for the agreements that reduced the <a href='nicaraguan-proxy-war.html'>Nicaraguan Proxy War</a> and created the country's post-Somoza constitutional order. It combined a coalition civilian government, reorganized constabulary, partial integration of nationalist fighters, local elections, American access and security guarantees, and continuing armed exclusion zones.",
    canon:"A settlement around 1980–82 with the stated institutional components, an American strategic advantage, incomplete disarmament, and continuing instability is established. Exact signature date, official treaty title, signatories, constitutional text, force quotas, election calendar, territorial limits of exclusion zones, and later amendments remain open.",
    sections:[
      {id:"negotiations",title:"Negotiations",html:"<p>Negotiations followed the failure of the provisional coalition to command the Guard remnants and armed nationalist factions. American officials, Nicaraguan civilians, military representatives, church intermediaries, and regional governments participated at different stages.</p>"},
      {id:"government",title:"Coalition government",html:"<p>The settlement preserved a civilian cabinet and legal political competition. No single revolutionary faction or former Guard command received exclusive authority over the successor state.</p>"},
      {id:"security",title:"Security institutions",html:"<p>A reorganized national constabulary replaced the Guard as the accepted state force. Vetting, command, local recruitment, integration of nationalist fighters, pensions, prosecutions, and weapons registration remained contested.</p>"},
      {id:"access",title:"American guarantees and access",html:"<p>The United States guaranteed the external settlement and retained access required to exclude Cuban or other rival military control. The arrangement placed Nicaragua inside the American security system without making every domestic institution an American office.</p>"},
      {id:"elections",title:"Elections and local government",html:"<p>Local elections and civilian administration reopened political space beyond the capital. Armed movements converted some organizations into parties, associations, cooperatives, or veterans' networks.</p>"},
      {id:"zones",title:"Armed exclusion zones",html:"<p>Some rural and frontier districts remained outside complete constabulary control. Local armed formations retained weapons or special guarantees while negotiators deferred final demobilization.</p>"},
      {id:"foreign",title:"Foreign reactions",html:"<p>Washington treated the agreement as a strategic victory. Cuba and Latin supporters accepted it unevenly, distinguishing preservation of nationalist participation from American restrictions on foreign military alignment.</p>"},
      {id:"legacy",title:"Legacy",html:"<p>The settlement ended the most dangerous phase of the war without resolving the revolution. Later disputes concerned land, former Guard property, missing persons, currency policy, foreign corporations, and the legal status of armed local networks.</p>"}
    ],
    related:[{href:"nicaraguan-proxy-war.html",kicker:"Conflict settled",label:"Nicaraguan Proxy War"},{href:"nicaraguan-national-guard.html",kicker:"Institution reorganized",label:"Nicaraguan National Guard"},{href:"sandinismo-nicaragua.html",kicker:"Movement partly integrated",label:"Sandinismo in Nicaragua"},{href:"nicaragua.html",kicker:"Successor republic",label:"Nicaragua"},{href:"central-american-security-corridor.html",kicker:"Security guarantee",label:"Central American Security Corridor"},{href:"costa-rica.html",kicker:"Regional mediator",label:"Costa Rica"}],
    categories:["Managua Settlement","Peace agreements of Nicaragua","Nicaraguan Proxy War","American Hemisphere"],
    facts:[["Period","c. 1980–1982"],["Location","Managua and regional negotiations"],["Political result","Coalition civilian government"],["Security result","Reorganized constabulary"],["Armed integration","Partial"],["Foreign guarantee","United States"],["Local elections","Provided"],["Disarmament","Incomplete"]]
  }),
  "guatemalan-insurgency":centralAmericanCrisisArticle({title:"Guatemalan Insurgency",category:"Wars involving Guatemala",eyebrow:"1960s–1980s · land, region, and military rule",infoboxKicker:"Internal conflict",
    lead:"The Guatemalan Insurgency is the continuing internal conflict between the American-aligned Guatemalan security state and multiple rural, Indigenous, agrarian, labor, Catholic-social, and military-reform movements. It follows the land and state crises that historically produced the Guatemalan Civil War but lacks a single Soviet-directed revolutionary coalition.",
    canon:"The conflict's roots in the 1944 opening, agrarian reform and reaction, landholding, Indigenous exclusion, military politics, foreign concessions, American assistance, regional and Catholic factions, counterinsurgency methods, Belize frontier effect, and continuation in 1985 are established. Exact start and end dates, rebel organizations, leaders, campaign names, casualty totals, and final peace settlement remain open.",
    sections:[
      {id:"origins",title:"Origins",html:"<p>The 1944 political opening expanded labor organization, education, and reform. Attempts to redistribute land and regulate foreign property brought landowners, officers, corporate interests, and American security policy into a common reaction.</p>"},
      {id:"movements",title:"Insurgent movements",html:"<p>Movements developed among Maya regions, agrarian communities, labor nationalists, displaced reformers, Catholic organizers, students, and dissident military officers. Local objectives and ethnic geography prevented one command from representing every conflict.</p>"},
      {id:"state",title:"Security state",html:"<p>The armed forces, intelligence services, police, military zones, and local auxiliaries became the most continuous national institutions. Civilian constitutions and elections operated around the emergency-security core.</p>"},
      {id:"operations",title:"Counterinsurgency",html:"<p>Government operations used patrol zones, road and air mobility, intelligence files, detention, population control, local defense groups, and American training. Armed organizations used mountain and forest routes, taxation, ambush, political organization, and cross-border refuge.</p>"},
      {id:"maya",title:"Maya communities",html:"<p>Maya peoples experienced military control, forced recruitment, displacement, village violence, and pressure from insurgents as well as the state. Indigenous political demands could not be reduced to the programs of Spanish-speaking national organizations.</p>"},
      {id:"religion",title:"Catholic conflict",html:"<p>Conservative Catholic officers and landholders presented order as defense of Christian society. Priests, lay workers, cooperatives, and agrarian reformers used Catholic social doctrine to organize communities, producing conflict within the church's own institutions.</p>"},
      {id:"foreign",title:"Foreign relations",html:"<p>The United States supplied equipment, credit, intelligence, training, and diplomatic protection. Britain and the Commonwealth defended Belize. Latin influence moved through church, education, publication, and commerce rather than an accepted combat mission.</p>"},
      {id:"status",title:"Status in 1985",html:"<p>Government forces controlled the principal cities, transport, and formal state, but regional war and coercive administration continued. No national peace agreement or complete military victory had been established.</p>"}
    ],
    related:[{href:"guatemala.html",kicker:"Country article",label:"Guatemala"},{href:"central-american-crisis.html",kicker:"Regional conflict",label:"Central American Crisis"},{href:"central-american-security-corridor.html",kicker:"Foreign support system",label:"Central American Security Corridor"},{href:"salvadoran-insurgency.html",kicker:"Neighboring conflict",label:"Salvadoran Insurgency"},{href:"belize.html",kicker:"Frontier dispute",label:"Belize"},{href:"honduras.html",kicker:"Logistics neighbor",label:"Honduras"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Guatemalan_Civil_War",label:"Wikipedia — Guatemalan Civil War (shared historical baseline)"}],categories:["Guatemalan Insurgency","Wars involving Guatemala","Counterinsurgency","American Hemisphere"],
    facts:[["Period","1960s–1980s"],["Location","Guatemala"],["Government alignment","American Hemisphere"],["Principal state institution","Armed forces"],["Principal social issue","Land and Indigenous exclusion"],["External state patron","United States"],["Soviet direction","Absent"],["Status in 1985","Continuing"]]
  }),
  "salvadoran-insurgency":centralAmericanCrisisArticle({title:"Salvadoran Insurgency",category:"Wars involving El Salvador",eyebrow:"Late 1970s–1980s · fragmented internal war",infoboxKicker:"Internal conflict",
    lead:"The Salvadoran Insurgency is the internal war among El Salvador's military-oligarchic state, rural and urban armed organizations, labor nationalists, Catholic-social reformers, and more radical revolutionary groups. American aid prevents state collapse, while Cuban and Latin networks support different opposition factions without creating a unified Soviet-style front.",
    canon:"The late-century conflict, roots in land concentration and 1932 memory, military government, urban and rural insurgency, Catholic-social division, American assistance, Cuban and Latin support, Honduran frontier tension, ideological fragmentation, brutality, and continuation in 1985 are established. Exact start and end dates, organization names, leaders, battles, casualty totals, and final settlement remain open.",
    sections:[
      {id:"background",title:"Background",html:"<p>Dense settlement, concentrated agricultural land, low rural wages, urban labor organization, and restricted electoral channels created long-term conflict. The 1932 uprising and mass killing remained a warning invoked by both the state and its opponents.</p>"},
      {id:"state",title:"Government and armed forces",html:"<p>Military officers, police, intelligence services, business associations, parties, and civilian officials shared authority unequally. Emergency powers and armed-force judgments defined which electoral outcomes the state considered survivable.</p>"},
      {id:"opposition",title:"Opposition movements",html:"<p>Rural organizations demanded land, wages, and protection from local coercion. Urban groups organized students, workers, professionals, and neighborhoods. Catholic activists, democratic reformers, labor nationalists, and revolutionary factions disagreed over the acceptable postwar state.</p>"},
      {id:"war",title:"Military operations",html:"<p>The conflict combined rural ambush, urban attacks, raids, arrests, local defense groups, intelligence penetration, road security, and coercion of civilian communities. Neither side established a complete national command or decisive military advantage.</p>"},
      {id:"america",title:"American assistance",html:"<p>The United States supplied equipment, training, communications, air mobility, credit, intelligence, and political support. Assistance preserved the government while increasing American influence over professionalization, elections, and regional coordination.</p>"},
      {id:"latin",title:"Cuban and Latin networks",html:"<p>Cuba supported armed anti-American factions. Spanish, Italian, and other Latin networks supplied religious, exile, publication, diplomatic, and financial connections. Opposition organizations received unequal support and retained distinct programs.</p>"},
      {id:"honduras",title:"Honduran frontier",html:"<p>Migration, land disputes, expulsions, smuggling, and military rivalry made the Honduran border a recurrent crisis line. Washington attempted to prevent fighting between two aligned security states from disrupting the wider corridor.</p>"},
      {id:"status",title:"Status in 1985",html:"<p>El Salvador remained formally sovereign and American-aligned. The government held the capital and formal institutions, but the insurgency, emergency powers, displacement, and political killings prevented a settled constitutional order.</p>"}
    ],
    related:[{href:"el-salvador.html",kicker:"Country article",label:"El Salvador"},{href:"central-american-crisis.html",kicker:"Regional conflict",label:"Central American Crisis"},{href:"central-american-security-corridor.html",kicker:"Government support system",label:"Central American Security Corridor"},{href:"guatemalan-insurgency.html",kicker:"Neighboring conflict",label:"Guatemalan Insurgency"},{href:"honduras.html",kicker:"Frontier state",label:"Honduras"},{href:"costa-rica.html",kicker:"Regional mediator",label:"Costa Rica"}],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/Salvadoran_Civil_War",label:"Wikipedia — Salvadoran Civil War (shared historical baseline)"},{href:"https://en.wikipedia.org/wiki/Football_War",label:"Wikipedia — Football War (Honduran–Salvadoran historical baseline)"}],categories:["Salvadoran Insurgency","Wars involving El Salvador","Counterinsurgency","American Hemisphere"],
    facts:[["Period","Late 1970s–1980s"],["Location","El Salvador"],["Government alignment","American Hemisphere"],["Principal state force","Armed Forces of El Salvador"],["Opposition","Multiple rural and urban factions"],["Government patron","United States"],["Opposition support","Cuban and Latin networks"],["Status in 1985","Continuing"]]
  })
});

const appendCentralAmericanRelated=(key,items)=>{
  const article=window.deepArticles[key];
  if(!article)return;
  article.related=article.related||[];
  for(const item of items)if(!article.related.some(existing=>existing.href===item.href))article.related.push(item);
};

if(window.deepArticles.nicaragua){
  const article=window.deepArticles.nicaragua;
  article.lead="Nicaragua is an American-aligned Central American republic formed through the incomplete settlement of the <a href='nicaraguan-proxy-war.html'>Nicaraguan Proxy War</a>. A broad <a href='sandinismo-nicaragua.html'>Sandinista tradition</a>, former <a href='nicaraguan-national-guard.html'>National Guard</a> networks, coalition institutions, local armed zones, American guarantees, Cuban support, and Latin political connections continue to shape the state in 1985.";
  article.canon="American alignment, the late-1970s collapse of the Somoza dynasty, a broad non-Marxist Sandinista conflict, Cuban and Latin support for anti-American factions, Honduran support for the American-backed side, and an uneasy Managua settlement around 1980–82 are established. Exact leaders, war dates, faction names, constitutional provisions, and demobilization totals remain open.";
  const replacements={
    sandinistas:"<p><a href='sandinismo-nicaragua.html'>Sandinismo</a> draws on national sovereignty, anti-dynastic memory, agrarian reform, student politics, Catholic social action, and resistance to American control. No Soviet center exists to impose one disciplined Marxist coalition. Cuba supplies the most direct foreign assistance to armed anti-American factions.</p>",
    foreign:"<p>Washington supplies security assistance and political limits through the <a href='central-american-security-corridor.html'>Central American Security Corridor</a>. Cuba assists armed anti-American factions. Spain, Italy, and other Latin networks provide political, church, exile, publishing, and commercial access.</p>",
    war:"<p>The Somoza regime collapsed during the late 1970s. A provisional coalition entered Managua, armed nationalists rejected American restrictions, Guard remnants resisted dissolution, Cuba and Latin states supported opposition factions, and Honduras supported the American-backed side.</p>",
    open:"<p>The <a href='managua-settlement.html'>Managua Settlement</a> of about 1980–82 created a coalition civilian government, reorganized constabulary, partial integration of nationalist fighters, local elections, American access and security guarantees, and continuing armed exclusion zones. It reduced the war without completing the revolution.</p>"
  };
  for(const section of article.sections||[])if(replacements[section.id]){section.html=replacements[section.id];if(section.id==="open")section.title="Managua Settlement";}
  article.facts=[["Capital","Managua"],["Government","Coalition republic"],["1985 alignment","American Hemisphere"],["Principal armed tradition","Broad non-Marxist Sandinismo"],["Soviet patronage","Absent"],["Cuban role","Support for anti-American factions"],["Security guarantor","United States"],["Settlement","Managua Settlement, c. 1980–82"]];
}

